insert into public.categories (id, slug, name, seo_plural, person_noun, icon, description, keywords, faq, avg_price_from, sort_order) values
  ('b912559b-6676-5c6a-a111-b7d7fedf3627', 'sprzatanie', 'Sprzątanie', 'Sprzątanie', 'osoba do sprzątania', 'Sparkles', 'Sprzątanie mieszkań, domów i biur, mycie okien, pranie tapicerki i sprzątanie po remoncie.', array['sprzątanie','sprzątaczka','mycie okien','porządki','pranie tapicerki','sprzątanie po remoncie']::text[], '[{"question":"Ile kosztuje sprzątanie mieszkania?","answer":"Standardowe sprzątanie mieszkania do 50 m² kosztuje zwykle od 150 do 250 zł. Cena zależy od metrażu, stanu mieszkania i dodatkowych usług, np. mycia okien czy piekarnika."},{"question":"Czy muszę mieć własne środki czystości?","answer":"Nie. Większość specjalistów przyjeżdża z własnymi środkami i sprzętem. Jeśli masz preferowane produkty, napisz o tym w rezerwacji."},{"question":"Jak szybko mogę umówić sprzątanie?","answer":"Wielu specjalistów ma wolne terminy jeszcze w tym samym tygodniu. Filtr „Dostępni dziś” pokaże osoby, które mogą przyjechać najszybciej."}]'::jsonb, 120, 0),
  ('869b14fb-04e7-55ad-ab21-3a0e9193ae5e', 'hydraulik', 'Hydraulik', 'Hydraulicy', 'hydraulik', 'Droplets', 'Naprawa przecieków, udrażnianie odpływów, montaż baterii, WC, pieców i instalacji wodno-kanalizacyjnych.', array['hydraulik','przeciek','cieknie','kran','bateria','zlew','wc','odpływ','rura','piec','woda','kanalizacja']::text[], '[{"question":"Ile kosztuje wizyta hydraulika?","answer":"Dojazd i diagnoza kosztują zwykle od 80 do 150 zł. Drobne naprawy, np. wymiana baterii, to koszt od 100 zł plus części."},{"question":"Czy hydraulik przyjedzie w nagłym przypadku?","answer":"Tak. Część specjalistów oferuje wyjazdy awaryjne tego samego dnia — szukaj oznaczenia „Dostępny dziś”."},{"question":"Czy dostanę fakturę?","answer":"Specjaliści prowadzący działalność wystawiają faktury. Informację znajdziesz w sekcji „Informacje o wykonawcy” na profilu."}]'::jsonb, 100, 1),
  ('e588083e-bbe1-567a-aa92-f54f1d7c994a', 'elektryk', 'Elektryk', 'Elektrycy', 'elektryk', 'Zap', 'Instalacje elektryczne, montaż oświetlenia i gniazdek, pomiary, rozdzielnice i usuwanie awarii.', array['elektryk','prąd','gniazdko','lampa','oświetlenie','bezpiecznik','instalacja elektryczna','pomiary','rozdzielnica']::text[], '[{"question":"Ile kosztuje elektryk za godzinę?","answer":"Stawki elektryków na Śląsku wynoszą zwykle od 80 do 150 zł za godzinę. Wiele prac, np. montaż lampy, wycenianych jest ryczałtowo."},{"question":"Czy elektryk ma uprawnienia SEP?","answer":"Zweryfikowani elektrycy w SWOJ dodają uprawnienia SEP w sekcji „Certyfikaty”. Sprawdź je przed rezerwacją."},{"question":"Czy mogę zamówić pomiary instalacji?","answer":"Tak. Pomiary elektryczne z protokołem oferuje większość elektryków z uprawnieniami pomiarowymi."}]'::jsonb, 100, 2),
  ('fa2a780c-072a-5f06-ad31-439ba8126c4d', 'zlota-raczka', 'Złota rączka', 'Złote rączki', 'złota rączka', 'Wrench', 'Drobne naprawy w domu: wieszanie półek i karniszy, regulacja drzwi i okien, montaż i poprawki.', array['złota rączka','naprawa','drobne naprawy','półka','karnisz','drzwi','zawieszenie','montaż']::text[], '[{"question":"Co może zrobić złota rączka?","answer":"Drobne prace montażowe i naprawcze: wieszanie półek, karniszy i telewizorów, regulacja drzwi, uszczelnianie, drobne naprawy mebli."},{"question":"Jak rozliczana jest praca?","answer":"Najczęściej godzinowo — od 70 do 120 zł za godzinę. Przy rezerwacji widzisz cenę „od” i szacowany czas."},{"question":"Czy muszę kupić materiały?","answer":"Zależy od zlecenia. Możesz dopisać w rezerwacji, że chcesz, by specjalista przywiózł potrzebne materiały."}]'::jsonb, 80, 3),
  ('10711627-4045-562b-a022-62306e0f6f34', 'montaz-mebli', 'Montaż mebli', 'Montaż mebli', 'monter mebli', 'Armchair', 'Skręcanie mebli z paczek, montaż szaf, kuchni i zabudów, demontaż i przeniesienie mebli.', array['montaż mebli','skręcanie mebli','ikea','szafa','kuchnia','meble','zabudowa']::text[], '[{"question":"Ile kosztuje skręcenie szafy?","answer":"Montaż szafy dwudrzwiowej kosztuje zwykle od 120 do 200 zł. Duże szafy z przesuwnymi drzwiami — od 250 zł."},{"question":"Czy monter przywiezie narzędzia?","answer":"Tak, specjaliści przyjeżdżają z kompletem narzędzi, w tym wkrętarką i poziomicą."},{"question":"Czy mogę zamówić montaż kuchni?","answer":"Tak. Montaż kuchni wyceniany jest zwykle za metr bieżący zabudowy."}]'::jsonb, 90, 4),
  ('f969bc78-f306-5091-ae37-1eb275f954f6', 'malowanie', 'Malowanie', 'Malarze', 'malarz', 'PaintRoller', 'Malowanie ścian i sufitów, gładzie, tapetowanie, malowanie elewacji i drobne prace wykończeniowe.', array['malowanie','malarz','ściany','sufit','gładź','tapeta','farba']::text[], '[{"question":"Ile kosztuje malowanie za m²?","answer":"Malowanie dwukrotne ścian kosztuje zwykle od 12 do 25 zł za m² robocizny. Gładzie to dodatkowy koszt."},{"question":"Ile trwa pomalowanie mieszkania?","answer":"Mieszkanie 50 m² to zazwyczaj 2–4 dni pracy, w zależności od przygotowania ścian."},{"question":"Czy malarz zabezpieczy meble i podłogi?","answer":"Tak, zabezpieczenie folią i taśmą jest standardem. Upewnij się, że jest ujęte w opisie usługi."}]'::jsonb, 15, 5),
  ('fd69d657-89c5-5c4e-a979-072411cbe300', 'remont', 'Remont', 'Ekipy remontowe', 'fachowiec od remontów', 'Hammer', 'Remonty łazienek i kuchni, układanie płytek i paneli, wykończenia wnętrz pod klucz.', array['remont','łazienka','płytki','glazura','panele','wykończenie','kafelki','wyremontować']::text[], '[{"question":"Ile kosztuje remont łazienki?","answer":"Remont łazienki 4–6 m² to zwykle koszt robocizny od 8 000 do 15 000 zł. Najlepiej wysłać zapytanie ze zdjęciami — specjaliści przygotują wycenę."},{"question":"Jak zamówić wycenę remontu?","answer":"Kliknij „Wyślij zapytanie”, opisz zakres prac i dodaj zdjęcia. Specjaliści z okolicy odpowiedzą z propozycją."},{"question":"Czy ekipa zajmie się wywozem gruzu?","answer":"Wiele ekip oferuje wywóz gruzu jako dodatkową opcję. Zapytaj o to w zapytaniu."}]'::jsonb, 150, 6),
  ('d5d15bda-1d17-546b-a878-0e546d775237', 'ogrod', 'Ogród', 'Ogrodnicy', 'ogrodnik', 'Trees', 'Koszenie trawy, przycinanie drzew i żywopłotów, zakładanie ogrodów, sprzątanie liści.', array['ogród','ogrodnik','koszenie','trawa','żywopłot','drzewa','liście','trawnik']::text[], '[{"question":"Ile kosztuje koszenie trawnika?","answer":"Koszenie do 500 m² to zwykle od 100 do 180 zł, z wywozem trawy od 150 zł."},{"question":"Czy ogrodnik przytnie wysokie drzewa?","answer":"Część specjalistów ma uprawnienia do pracy na wysokości. Sprawdź opis usług na profilu."},{"question":"Czy mogę zamówić stałą opiekę nad ogrodem?","answer":"Tak, wielu ogrodników oferuje regularne wizyty w sezonie. Napisz o tym w zapytaniu."}]'::jsonb, 100, 7),
  ('af9d7424-9642-5d53-a2cd-089edbcb0062', 'przeprowadzki', 'Przeprowadzki', 'Przeprowadzki', 'firma przeprowadzkowa', 'Truck', 'Przeprowadzki mieszkań i biur, transport mebli, wnoszenie, pakowanie i wywóz.', array['przeprowadzka','transport','przewóz','meble','bus','wywóz','tragarze']::text[], '[{"question":"Ile kosztuje przeprowadzka w obrębie miasta?","answer":"Przeprowadzka kawalerki w obrębie jednego miasta to zwykle od 400 do 800 zł. Duże mieszkania wyceniane są indywidualnie."},{"question":"Czy ekipa spakuje rzeczy?","answer":"Pakowanie i kartony są zwykle dostępne jako opcje dodatkowe."},{"question":"Czy mienie jest ubezpieczone?","answer":"Sprawdź w sekcji „Informacje o wykonawcy”, czy firma ma OC przewoźnika."}]'::jsonb, 150, 8),
  ('61625d5e-e168-52ec-a857-fe5dbb6b6871', 'naprawa-agd', 'AGD i klimatyzacja', 'Serwis AGD i klimatyzacji', 'serwisant', 'WashingMachine', 'Naprawa pralek, zmywarek i lodówek, montaż i serwis klimatyzacji, podłączanie sprzętu.', array['agd','pralka','zmywarka','lodówka','piekarnik','klimatyzacja','klima','serwis']::text[], '[{"question":"Ile kosztuje naprawa pralki?","answer":"Diagnoza z dojazdem to zwykle 100–150 zł. Koszt naprawy zależy od części."},{"question":"Ile kosztuje montaż klimatyzacji?","answer":"Montaż standardowy klimatyzatora split to zwykle od 1 200 zł robocizny."},{"question":"Jak często serwisować klimatyzację?","answer":"Producenci zalecają przegląd raz w roku, najlepiej przed sezonem."}]'::jsonb, 120, 9),
  ('99ec1ca1-5656-5edb-a71d-068d2cf6f182', 'beauty', 'Beauty', 'Usługi beauty', 'stylistka', 'Scissors', 'Fryzjer, barber, kosmetyczka, manicure, makijaż i masaż — w salonie lub z dojazdem.', array['fryzjer','barber','kosmetyczka','manicure','paznokcie','makijaż','masaż','strzyżenie','brwi','rzęsy']::text[], '[{"question":"Czy mogę zamówić fryzjera z dojazdem?","answer":"Tak. Na profilu sprawdź „Obszar działania” — wielu specjalistów dojeżdża do klienta."},{"question":"Jak odwołać wizytę?","answer":"Rezerwację możesz odwołać w panelu klienta. Zasady odwołania ustala każdy specjalista."},{"question":"Czy widzę ceny przed rezerwacją?","answer":"Tak, każda usługa ma cenę „od” i szacowany czas trwania."}]'::jsonb, 60, 10),
  ('97e0d4a3-0b9b-596d-a264-6dda8e65c912', 'korepetycje', 'Korepetycje', 'Korepetytorzy', 'korepetytor', 'GraduationCap', 'Matematyka, języki obce, przygotowanie do matury i egzaminu ósmoklasisty — stacjonarnie i online.', array['korepetycje','matematyka','angielski','matura','egzamin','nauka','lekcje','niemiecki','fizyka']::text[], '[{"question":"Ile kosztują korepetycje z matematyki?","answer":"Lekcja 60 minut kosztuje zwykle od 60 do 120 zł, zależnie od poziomu."},{"question":"Czy są zajęcia online?","answer":"Tak. Wielu korepetytorów prowadzi lekcje online — sprawdź opis usług."},{"question":"Czy mogę umówić lekcję próbną?","answer":"Część korepetytorów oferuje krótszą lekcję próbną w niższej cenie."}]'::jsonb, 60, 11),
  ('5aa65eea-059b-55ea-a850-166b29eaa6b6', 'fotografia', 'Fotografia', 'Fotografowie', 'fotograf', 'Camera', 'Sesje rodzinne i biznesowe, reportaże z uroczystości, zdjęcia produktowe i nieruchomości.', array['fotograf','sesja','zdjęcia','ślub','chrzest','portret','fotografia produktowa']::text[], '[{"question":"Ile kosztuje sesja zdjęciowa?","answer":"Krótka sesja portretowa to zwykle od 300 zł. Reportaże z uroczystości wyceniane są godzinowo lub pakietowo."},{"question":"Kiedy dostanę zdjęcia?","answer":"Zwykle w ciągu 7–21 dni. Termin oddania znajdziesz w opisie usługi."},{"question":"Czy zobaczę portfolio?","answer":"Tak, każdy fotograf ma sekcję „Portfolio” na profilu."}]'::jsonb, 300, 12),
  ('63ba18ec-a50f-5872-a866-f5f1d4deb5f2', 'zwierzeta', 'Zwierzęta', 'Opiekunowie zwierząt', 'opiekun zwierząt', 'PawPrint', 'Wyprowadzanie psów, opieka nad zwierzętami podczas wyjazdu, groomer i szkolenie psów.', array['pies','kot','spacer','opieka','zwierzęta','groomer','behawiorysta','wyprowadzanie']::text[], '[{"question":"Ile kosztuje spacer z psem?","answer":"Spacer 30–60 minut kosztuje zwykle od 30 do 50 zł."},{"question":"Czy opiekun może zostać u mnie na noc?","answer":"Tak, część opiekunów oferuje opiekę nocną w domu właściciela."},{"question":"Czy mogę poznać opiekuna wcześniej?","answer":"Polecamy wysłać zapytanie i umówić krótkie spotkanie zapoznawcze."}]'::jsonb, 40, 13),
  ('02fc7f14-103a-512e-a419-34961a1b6cc8', 'biznes', 'Biznes i online', 'Usługi dla firm', 'specjalista', 'Briefcase', 'Księgowość, strony internetowe, grafika, tłumaczenia, marketing i obsługa IT dla małych firm.', array['księgowa','księgowość','strona internetowa','grafik','logo','tłumacz','marketing','it','online','biuro rachunkowe']::text[], '[{"question":"Czy usługi biznesowe są dostępne online?","answer":"Tak, większość usług z tej kategorii realizowana jest zdalnie, niezależnie od miasta."},{"question":"Czy dostanę fakturę VAT?","answer":"Specjaliści prowadzący działalność wystawiają faktury VAT."},{"question":"Jak porównać oferty?","answer":"Wyślij jedno zapytanie — kilku specjalistów odpowie z wyceną i terminem."}]'::jsonb, 150, 14);
