insert into public.providers (id, slug, first_name, last_name, gender, headline, bio, primary_category_id, location_id, district, service_radius_km, years_experience, skills, languages, experience, certificates, provider_type, company_name, verified, response_time_hours, availability, plan, featured, avatar_hue, member_since, status) values
  ('9d2f786b-b1c0-5333-a92f-204f940cf6ca', 'marek-kowalski-elektryk-katowice', 'Marek', 'Kowalski', 'm', 'Elektryk z uprawnieniami SEP. Instalacje, oświetlenie i awarie.', 'Od 14 lat zajmuję się instalacjami elektrycznymi w mieszkaniach i domach na Śląsku. Pracuję czysto, tłumaczę, co robię, i zostawiam protokół z pomiarów. Najczęściej modernizuję stare instalacje w blokach i kamienicach, montuję oświetlenie LED i usuwam awarie.', 'e588083e-bbe1-567a-aa92-f54f1d7c994a', '2dc25850-873b-52c4-a2c8-25039cac650d', 'Ligota', 30, 14, array['Instalacje elektryczne','Oświetlenie LED','Pomiary elektryczne','Rozdzielnice','Smart Home','Usuwanie awarii','Drobne naprawy']::text[], array['polski','angielski']::text[], '[{"role":"Działalność własna","company":"Elektro-Kowalski","from":2018,"to":null,"description":"Elektryk z uprawnieniami SEP. Instalacje, oświetlenie i awarie."},{"role":"Specjalista","company":"Tauron Dystrybucja","from":2012,"to":2018,"description":"Praca w zespole, instalacje elektryczne i oświetlenie led."}]'::jsonb, '[{"name":"Uprawnienia SEP E do 1 kV","issuer":"Stowarzyszenie Elektryków Polskich","year":2015},{"name":"Uprawnienia SEP D (dozór)","issuer":"Stowarzyszenie Elektryków Polskich","year":2022}]'::jsonb, 'sole_trader', 'Elektro-Kowalski', true, 1, 'today', 'pro_plus', true, 265, 2024, 'published'),
  ('d821acbd-e037-5227-aea2-cfcb0e2f50c7', 'anna-nowak-sprzatanie-katowice', 'Anna', 'Nowak', 'f', 'Sprzątanie mieszkań i biur. Własne, ekologiczne środki.', 'Sprzątam tak, jak chciałabym, żeby sprzątano u mnie. Przyjeżdżam z własnym sprzętem i ekologicznymi środkami. Mam stałych klientów w Katowicach i Chorzowie, chętnie przyjmę kolejnych.', 'b912559b-6676-5c6a-a111-b7d7fedf3627', '2dc25850-873b-52c4-a2c8-25039cac650d', 'Brynów', 20, 6, array['Sprzątanie mieszkań','Mycie okien','Pranie tapicerki','Ekologiczne środki','Sprzątanie biur']::text[], array['polski']::text[], '[{"role":"Działalność własna","company":"Anna Nowak","from":2022,"to":null,"description":"Sprzątanie mieszkań i biur. Własne, ekologiczne środki."},{"role":"Specjalista","company":"Clean Service Śląsk","from":2020,"to":2022,"description":"Praca w zespole, sprzątanie mieszkań i mycie okien."}]'::jsonb, '[{"name":"Profesjonalne sprzątanie i dezynfekcja","issuer":"Akademia Czystości","year":2022}]'::jsonb, 'sole_trader', null, true, 1, 'tomorrow', 'pro', true, 339, 2022, 'published'),
  ('9fc39ee2-1fac-5aef-ad7a-7c7adf082f05', 'piotr-wisniewski-hydraulik-gliwice', 'Piotr', 'Wiśniewski', 'm', 'Hydraulik — przecieki, armatura, instalacje wod-kan.', 'Specjalizuję się w szybkich naprawach i wymianie instalacji w mieszkaniach. W nagłych przypadkach przyjeżdżam jeszcze tego samego dnia. Gliwice, Zabrze i okolice.', '869b14fb-04e7-55ad-ab21-3a0e9193ae5e', '7b86db9d-1755-5b23-ae4e-d61f884b9196', 'Sośnica', 25, 12, array['Instalacje wod-kan','Usuwanie przecieków','Montaż armatury','Udrażnianie','Instalacje gazowe']::text[], array['polski']::text[], '[{"role":"Działalność własna","company":"Piotr Wiśniewski","from":2019,"to":null,"description":"Hydraulik — przecieki, armatura, instalacje wod-kan."},{"role":"Specjalista","company":"Wodociągi Śląskie","from":2014,"to":2019,"description":"Praca w zespole, instalacje wod-kan i usuwanie przecieków."}]'::jsonb, '[{"name":"Uprawnienia gazowe G3","issuer":"Stowarzyszenie Elektryków Polskich","year":2022},{"name":"Certyfikowany instalator Geberit","issuer":"Geberit Polska","year":2017}]'::jsonb, 'sole_trader', null, true, 1, 'today', 'pro', true, 254, 2021, 'published'),
  ('66e70e58-9dfa-58bd-afe8-e331d7090ece', 'kamil-wojcik-zlota-raczka-tychy', 'Kamil', 'Wójcik', 'm', 'Złota rączka. Zrobię to, na co brakuje Ci czasu.', 'Półki, karnisze, telewizory, regulacja drzwi, silikony — zbieram listę drobnych prac i załatwiam je podczas jednej wizyty. Mam własne narzędzia i podstawowe materiały montażowe.', 'fa2a780c-072a-5f06-ad31-439ba8126c4d', '7d39a835-f501-5f62-a342-94870a72066c', null, 20, 8, array['Drobne naprawy','Montaż TV','Wieszanie półek','Regulacja okien i drzwi','Silikonowanie','Meble IKEA','Kuchnie']::text[], array['polski']::text[], '[{"role":"Działalność własna","company":"Kamil Wójcik","from":2021,"to":null,"description":"Złota rączka. Zrobię to, na co brakuje Ci czasu."},{"role":"Specjalista","company":"Domowa Pomoc s.c.","from":2018,"to":2021,"description":"Praca w zespole, drobne naprawy i montaż tv."}]'::jsonb, '[{"name":"Kurs montażu stolarki otworowej","issuer":"Akademia Budowlana","year":2019}]'::jsonb, 'freelancer', null, true, 1, 'tomorrow', 'free', true, 41, 2021, 'published'),
  ('342d7625-808c-5f2d-a187-74d27b7645a7', 'marta-kaminska-beauty-chorzow', 'Marta', 'Kamińska', 'f', 'Kosmetyczka. Pielęgnacja twarzy i manicure hybrydowy.', 'Prowadzę kameralny gabinet w centrum Chorzowa. Stawiam na zdrową skórę i naturalny efekt. Każdy zabieg zaczynam od krótkiej konsultacji.', '99ec1ca1-5656-5edb-a71d-068d2cf6f182', '9f1f74fd-1db5-509e-ac00-cf78fb7d4310', 'Centrum', 5, 9, array['Strzyżenie','Koloryzacja','Barbering','Manicure','Pielęgnacja twarzy','Masaż']::text[], array['polski']::text[], '[{"role":"Działalność własna","company":"Studio Marta","from":2021,"to":null,"description":"Kosmetyczka. Pielęgnacja twarzy i manicure hybrydowy."},{"role":"Specjalista","company":"Instytut Urody Lumi","from":2017,"to":2021,"description":"Praca w zespole, strzyżenie i koloryzacja."}]'::jsonb, '[{"name":"Mistrz fryzjerstwa","issuer":"Izba Rzemieślnicza w Katowicach","year":2019}]'::jsonb, 'sole_trader', 'Studio Marta', true, 1, 'this_week', 'pro', true, 330, 2023, 'published'),
  ('f13369b5-ded1-5a4b-a69b-f1bdceb2b47a', 'tomasz-zielinski-montaz-mebli-sosnowiec', 'Tomasz', 'Zieliński', 'm', 'Montaż mebli i kuchni. IKEA, BRW, Agata.', 'Składam meble z paczek, kuchnie i szafy na wymiar. Każdy mebel poziomuję i mocuję do ściany. Kartony zabieram ze sobą.', '10711627-4045-562b-a022-62306e0f6f34', '80050854-7cd5-5fc4-ad88-9b6cd7a1865e', null, 30, 7, array['Meble IKEA','Kuchnie','Szafy przesuwne','Garderoby','Mocowanie do ściany','Drobne naprawy','Montaż TV']::text[], array['polski']::text[], '[{"role":"Działalność własna","company":"Tomasz Zieliński","from":2022,"to":null,"description":"Montaż mebli i kuchni. IKEA, BRW, Agata."},{"role":"Specjalista","company":"Black Red White — serwis","from":2019,"to":2022,"description":"Praca w zespole, meble ikea i kuchnie."}]'::jsonb, '[{"name":"Autoryzowany monter kuchni","issuer":"IKEA Services Partner","year":2024}]'::jsonb, 'sole_trader', null, true, 3, 'tomorrow', 'pro', true, 303, 2021, 'published'),
  ('f4d93604-075b-5488-a380-993e3c47ff47', 'piotr-nowak-hydraulik-katowice', 'Piotr', 'Nowak', 'm', 'Hydraulik i serwis AGD. Szybkie terminy w Katowicach.', 'Naprawiam przecieki, wymieniam baterie i podłączam pralki oraz zmywarki. Jestem w Katowicach i okolicach, rano mam zwykle wolne okienka na pilne zgłoszenia.', '869b14fb-04e7-55ad-ab21-3a0e9193ae5e', '2dc25850-873b-52c4-a2c8-25039cac650d', 'Załęże', 20, 12, array['Instalacje wod-kan','Usuwanie przecieków','Montaż armatury','Udrażnianie','Instalacje gazowe','Pralki i zmywarki','Klimatyzacja']::text[], array['polski']::text[], '[{"role":"Działalność własna","company":"Piotr Nowak","from":2019,"to":null,"description":"Hydraulik i serwis AGD. Szybkie terminy w Katowicach."},{"role":"Specjalista","company":"Termo-Serwis s.c.","from":2014,"to":2019,"description":"Praca w zespole, instalacje wod-kan i usuwanie przecieków."}]'::jsonb, '[{"name":"Uprawnienia gazowe G3","issuer":"Stowarzyszenie Elektryków Polskich","year":2020},{"name":"Certyfikowany instalator Geberit","issuer":"Geberit Polska","year":2017}]'::jsonb, 'sole_trader', null, true, 2, 'tomorrow', 'pro', true, 69, 2021, 'published'),
  ('2c43a8f7-53e9-5f6f-ac10-7e25f68c200a', 'katarzyna-lewandowska-korepetycje-gliwice', 'Katarzyna', 'Lewandowska', 'f', 'Korepetycje z matematyki. Matura i egzamin ósmoklasisty.', 'Jestem nauczycielką matematyki w liceum. Uczę spokojnie i krok po kroku, tak żeby uczeń rozumiał, a nie tylko zapamiętywał. Zajęcia u mnie, u ucznia lub online.', '97e0d4a3-0b9b-596d-a264-6dda8e65c912', '7b86db9d-1755-5b23-ae4e-d61f884b9196', null, 10, 10, array['Matematyka','Matura','Egzamin ósmoklasisty','Angielski','Zajęcia online']::text[], array['polski']::text[], '[{"role":"Działalność własna","company":"Katarzyna Lewandowska","from":2020,"to":null,"description":"Korepetycje z matematyki. Matura i egzamin ósmoklasisty."},{"role":"Nauczyciel","company":"Szkoła Językowa Speak Up","from":2016,"to":2020,"description":"Praca w zespole, matematyka i matura."}]'::jsonb, '[{"name":"Magister matematyki","issuer":"Uniwersytet Śląski","year":2024}]'::jsonb, 'freelancer', null, true, 1, 'this_week', 'pro', true, 256, 2024, 'published'),
  ('faea6f9c-8e3a-5522-a87c-2b93d8d573b7', 'michal-szymanski-malowanie-zabrze', 'Michał', 'Szymański', 'm', 'Malarz. Gładzie, malowanie, tapetowanie.', 'Maluję mieszkania, biura i klatki schodowe. Zabezpieczam wszystko folią, a po pracy zostawiam porządek. Doradzę kolory i farby do każdego pomieszczenia.', 'f969bc78-f306-5091-ae37-1eb275f954f6', 'f4c698b3-dd9e-5828-a532-4419c9b5c677', null, 35, 15, array['Malowanie natryskowe','Gładzie','Tapetowanie','Farby dekoracyjne','Lamperie','Remonty łazienek','Płytki wielkoformatowe']::text[], array['polski']::text[], '[{"role":"Działalność własna","company":"Michał Szymański","from":2017,"to":null,"description":"Malarz. Gładzie, malowanie, tapetowanie."},{"role":"Specjalista","company":"Dekor-Ściany s.c.","from":2011,"to":2017,"description":"Praca w zespole, malowanie natryskowe i gładzie."}]'::jsonb, '[{"name":"Szkolenie aplikacji farb dekoracyjnych","issuer":"Tikkurila Akademia","year":2023}]'::jsonb, 'sole_trader', null, true, 6, 'this_week', 'free', true, 313, 2023, 'published'),
