  ('faa73a4e-1c42-559e-ac81-85995f79fe42', 'grzegorz-mazur-ogrod-rybnik', 'Grzegorz', 'Mazur', 'm', 'Ogrodnik. Koszenie, żywopłoty i zakładanie trawników.', 'Dbam o ogrody przydomowe w Rybniku, Żorach i okolicy. Mam własny sprzęt i przyczepę do wywozu zieleni.', 'd5d15bda-1d17-546b-a878-0e546d775237', '721de46a-a3c6-59cc-a28d-ec2cd25adc1e', null, 30, 11, array['Koszenie','Formowanie żywopłotów','Zakładanie trawników','Nawadnianie','Pielęgnacja drzew']::text[], array['polski']::text[], '[{"role":"Działalność własna","company":"Grzegorz Mazur","from":2019,"to":null,"description":"Ogrodnik. Koszenie, żywopłoty i zakładanie trawników."},{"role":"Specjalista","company":"Zielone Ogrody Rybnik","from":2015,"to":2019,"description":"Praca w zespole, koszenie i formowanie żywopłotów."}]'::jsonb, '[{"name":"Uprawnienia do pracy pilarką","issuer":"Centrum Szkoleń Leśnych","year":2021}]'::jsonb, 'sole_trader', null, true, 1, 'tomorrow', 'free', false, 17, 2024, 'published'),
