  ('4fbe969d-d93a-5b86-a527-084155219cd7', 'magdalena-piotrowska-zwierzeta-katowice', 'Magdalena', 'Piotrowska', 'f', 'Opieka nad psami i kotami. Spacery i wizyty domowe.', 'Kocham zwierzęta i mam doświadczenie z psami reaktywnymi. Po każdym spacerze wysyłam zdjęcie i krótką relację.', '63ba18ec-a50f-5872-a866-f5f1d4deb5f2', '2dc25850-873b-52c4-a2c8-25039cac650d', 'Osiedle Tysiąclecia', 8, 5, array['Spacery','Opieka nad kotami','Podawanie leków','Groomer','Psy reaktywne']::text[], array['polski']::text[], '[{"role":"Usługi prywatne","company":"Magdalena Piotrowska","from":2023,"to":null,"description":"Opieka nad psami i kotami. Spacery i wizyty domowe."},{"role":"Specjalista","company":"Schronisko dla zwierząt w Katowicach — wolontariat","from":2021,"to":2023,"description":"Praca w zespole, spacery i opieka nad kotami."}]'::jsonb, '[{"name":"Pierwsza pomoc dla zwierząt","issuer":"VetSzkolenia","year":2023}]'::jsonb, 'private', null, true, 3, 'today', 'free', false, 247, 2024, 'published'),
